export const normalize=x=>String(x).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
export function searchContent(query,items,limit=12){const tokens=normalize(query).split(/\s+/).filter(Boolean);if(!tokens.length)return [];return items.map(item=>{const title=normalize(item.title),body=normalize(item.text||'');return {...item,score:tokens.reduce((s,t)=>s+(title.includes(t)?5:body.includes(t)?1:0),0),matched:tokens.every(t=>title.includes(t)||body.includes(t))}}).filter(x=>x.matched).sort((a,b)=>b.score-a.score).slice(0,limit)}
export function calcRisk(control,treatment){if(![control,treatment].every(x=>Number.isFinite(x)&&x>=0&&x<=100))return null;const diff=control-treatment;return {difference:diff,relative:control?diff/control*100:null,nnt:diff===0?null:Math.ceil(100/Math.abs(diff)),harm:diff<0}}
export function calcBody(height,initial,current){if(![height,initial,current].every(Number.isFinite)||height<100||height>250||initial<25||initial>500||current<25||current>500)return null;return {bmi:current/(height/100)**2,loss:(initial-current)/initial*100,kg:initial-current}}
export const schedules={wegovy:{label:'Semaglutida SC · esquema clássico de obesidade',unit:'mg/semana',stages:[[4,.25],[4,.5],[4,1],[4,1.7],[4,2.4]],refs:['wegovy-ema']},tirzepatida:{label:'Tirzepatida · até primeiro degrau de manutenção',unit:'mg/semana',stages:[[4,2.5],[4,5]],refs:['mounjaro-ema']},saxenda:{label:'Liraglutida · obesidade',unit:'mg/dia',stages:[[1,.6],[1,1.2],[1,1.8],[1,2.4],[4,3]],refs:['saxenda-ema']},ozempic:{label:'Semaglutida SC · até primeiro degrau de DM2',unit:'mg/semana',stages:[[4,.25],[4,.5]],refs:['ozempic']}};
export function makeSchedule(name,start){const s=schedules[name];if(!s||!/^\d{4}-\d{2}-\d{2}$/.test(start))return [];const date=new Date(start+'T12:00:00Z');if(!Number.isFinite(date.getTime())||date.toISOString().slice(0,10)!==start)return [];let week=0;return s.stages.map(([weeks,dose])=>{const from=new Date(date.getTime()+week*7*864e5);week+=weeks;const to=new Date(date.getTime()+(week*7-1)*864e5);return {from:from.toISOString().slice(0,10),to:to.toISOString().slice(0,10),weeks,dose,unit:s.unit}})}
export function nextReview(quality,previous=0,now=Date.now()){const days=quality==='again'?0:quality==='hard'?1:Math.min(60,Math.max(3,previous?previous*2:3));return {interval:days,due:now+(quality==='again'?10*60e3:days*864e5)}}
export function escapeHtml(x){return String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
